67	/// `POST /collections/{collection}/records`：提交一批记录（全有或全无）。
68	async fn write_records(
69	    State(s): State<Arc<Store>>,
70	    Path(collection): Path<String>,
71	    payload: Result<Json<WriteRequest>, axum::extract::rejection::JsonRejection>,
72	) -> Result<Json<Value>, ApiError> {
73	    let Json(req) = payload.map_err(|e| ApiError::new(StatusCode::BAD_REQUEST, e.body_text()))?;
74	    if req.records.is_empty() {
75	        return Err(ApiError::new(
76	            StatusCode::BAD_REQUEST,
77	            "records must be a non-empty array",
78	        ));
79	    }
80	    match s.write_batch(&collection, &req.records, req.replace) {
81	        Ok(out) => {
82	            // replace=false（或缺省）时响应与原来完全一致；仅替换模式附加 "replaced"。
83	            let mut body = json!({
84	                "collection": out.collection,
85	                "accepted": out.accepted,
86	                "inserted": out.inserted,
87	            });
88	            if req.replace {
89	                body["replaced"] = json!(out.replaced);
90	            }
91	            Ok(Json(body))
92	        }
93	        Err(BatchError::Rejected(r)) => Err(ApiError {
94	            status: StatusCode::BAD_REQUEST,
95	            body: json!({
96	                "error": r.reason,
97	                "index": r.index,
98	                "id": r.id,
99	            }),
100	        }),
101	        Err(BatchError::Persist(msg)) => Err(ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, msg)),
102	    }
103	}
