105	/// `POST /versions`：保存当前各集合数据为只读版本。
106	async fn save_version(State(s): State<Arc<Store>>) -> Result<Response, ApiError> {
107	    let v = s
108	        .save_version()
109	        .map_err(|e| ApiError::new(StatusCode::INTERNAL_SERVER_ERROR, e))?;
110	    Ok((
111	        StatusCode::CREATED,
112	        Json(json!({ "id": v.id, "saved_at": v.saved_at })),
113	    )
114	        .into_response())
115	}
116	
117	/// `GET /versions`：列出已保存的版本。
118	async fn list_versions(State(s): State<Arc<Store>>) -> Json<Value> {
119	    let versions: Vec<Value> = s
120	        .list_versions()
121	        .into_iter()
122	        .map(|v| json!({ "id": v.id, "saved_at": v.saved_at }))
123	        .collect();
124	    Json(json!({ "versions": versions }))
125	}
126	
127	/// `GET /versions/{id}`：版本详情（含集合名列表）。
128	async fn get_version(
129	    State(s): State<Arc<Store>>,
130	    Path(id): Path<u64>,
131	) -> Result<Json<Value>, ApiError> {
132	    let d = s
133	        .get_version(id)
134	        .map_err(|e| lookup_error(e, "version", id))?;
135	    let mut collections = d.collections;
136	    collections.sort();
137	    Ok(Json(json!({
138	        "id": d.id,
139	        "saved_at": d.saved_at,
140	        "collections": collections,
141	    })))
142	}
143	
144	/// `GET /versions/{id}/collections/{collection}/records`：查询版本内集合的全部记录。
145	async fn read_records(
146	    State(s): State<Arc<Store>>,
147	    Path((version_id, collection)): Path<(u64, String)>,
148	) -> Result<Json<Value>, ApiError> {
149	    let records = s
150	        .read_records(version_id, &collection)
151	        .map_err(|e| lookup_error(e, &collection, version_id))?;
152	    Ok(Json(json!({
153	        "version": version_id,
154	        "collection": collection,
155	        "records": records,
156	    })))
157	}
158	
159	/// `GET /versions/{from}/collections/{collection}/diff/{to}`：
160	/// 比较同一集合在两个已保存版本之间的差异（只读，不生成新版本）。
161	async fn diff_versions(
162	    State(s): State<Arc<Store>>,
163	    Path((from, collection, to)): Path<(u64, String, u64)>,
164	) -> Result<Json<Value>, ApiError> {
165	    let d = s
166	        .diff_versions(from, to, &collection)
167	        .map_err(|e| diff_error(e, &collection, from, to))?;
168	    let changed: Vec<Value> = d
169	        .changed
170	        .iter()
171	        .map(|c| {
172	            json!({
173	                "id": c.before["id"],
174	                "before": c.before,
175	                "after": c.after,
176	            })
177	        })
178	        .collect();
179	    Ok(Json(json!({
180	        "from": d.from,
181	        "to": d.to,
182	        "collection": d.collection,
183	        "added": d.added,
184	        "dropped": d.dropped,
185	        "changed": changed,
186	    })))
187	}
188	
189	/// 差异查询的错误映射：版本/集合不存在为 404，起始版本晚于目标版本为 400。
190	fn diff_error(e: DiffError, collection: &str, from: u64, to: u64) -> ApiError {
191	    match e {
192	        DiffError::FromVersionNotFound => {
193	            ApiError::new(StatusCode::NOT_FOUND, format!("version {from} not found"))
194	        }
195	        DiffError::ToVersionNotFound => {
196	            ApiError::new(StatusCode::NOT_FOUND, format!("version {to} not found"))
197	        }
198	        DiffError::CollectionNotFoundInFrom => ApiError::new(
199	            StatusCode::NOT_FOUND,
200	            format!("collection \"{collection}\" not found in version {from}"),
201	        ),
202	        DiffError::CollectionNotFoundInTo => ApiError::new(
203	            StatusCode::NOT_FOUND,
204	            format!("collection \"{collection}\" not found in version {to}"),
205	        ),
206	        DiffError::OutOfOrder => ApiError::new(
207	            StatusCode::BAD_REQUEST,
208	            format!("start version {from} is later than target version {to}"),
209	        ),
210	    }
211	}
212	
213	/// 便于组合状态码与响应体。
214	fn lookup_error(e: LookupError, collection: &str, version: u64) -> ApiError {
215	    match e {
216	        LookupError::VersionNotFound => ApiError::new(
217	            StatusCode::NOT_FOUND,
218	            format!("version {version} not found"),
219	        ),
220	        LookupError::CollectionNotFound => ApiError::new(
221	            StatusCode::NOT_FOUND,
222	            format!("collection \"{collection}\" not found in version {version}"),
223	        ),
224	    }
225	}
