231	        .route(
232	            "/collections/{collection}/records",
233	            axum::routing::post(write_records),
234	        )
235	        .route(
236	            "/versions",
237	            axum::routing::post(save_version).get(list_versions),
238	        )
239	        .route("/versions/{id}", get(get_version))
240	        .route(
241	            "/versions/{id}/collections/{collection}/records",
242	            get(read_records),
243	        )
244	        .route(
245	            "/versions/{from}/collections/{collection}/diff/{to}",
246	            get(diff_versions),
247	        )
248	        .with_state(store)
249	}
250	
251	#[tokio::main]
252	async fn main() -> Result<(), Box<dyn Error>> {
253	    let bind = env::var("VDE_BIND").unwrap_or_else(|_| "127.0.0.1:8080".to_owned());
254	    let data_dir = env::var("VDE_DATA").unwrap_or_else(|_| "data".to_owned());
255	    let store = Arc::new(Store::open(&data_dir)?);
256	
257	    let listener = tokio::net::TcpListener::bind(&bind).await?;
258	    println!(
259	        "Listening on http://{} (data dir: {})",
260	        listener.local_addr()?,
261	        data_dir
262	    );
263	    axum::serve(listener, app(store))
264	        .with_graceful_shutdown(async {
265	            let _ = tokio::signal::ctrl_c().await;
266	        })
267	        .await?;
268	    Ok(())
