385	    /// 把当前各集合数据固化为只读版本，返回版本标识与保存时间。
386	    pub fn save_version(&self) -> Result<VersionSummary, String> {
387	        let mut st = self.inner.lock().unwrap();
388	        let id = st.next_id;
389	        let saved_at = now_ms();
390	        let data: HashMap<String, Vec<Record>> = st
391	            .current
392	            .iter()
393	            .map(|(name, records)| (name.clone(), records.clone()))
394	            .collect();
395	        st.versions.push(VersionSnap { id, saved_at, data });
396	        st.next_id += 1;
397	
398	        // 固化完整状态到快照文件，然后清空 WAL（旧提交已包含在快照中）。
399	        persist_state(&self.data_dir, &st)?;
400	        truncate_wal(&mut st.wal, &self.data_dir.join("wal.log"))?;
401	
402	        Ok(VersionSummary { id, saved_at })
403	    }
