405	    /// 查询指定版本内指定集合的全部记录（字段顺序与写入时一致）。
406	    pub fn read_records(
407	        &self,
408	        version_id: u64,
409	        collection: &str,
410	    ) -> Result<Vec<Record>, LookupError> {
411	        let st = self.inner.lock().unwrap();
412	        let version = st
413	            .versions
414	            .iter()
415	            .find(|v| v.id == version_id)
416	            .ok_or(LookupError::VersionNotFound)?;
417	        version
418	            .data
419	            .get(collection)
420	            .cloned()
421	            .ok_or(LookupError::CollectionNotFound)
