540	fn append_wal(wal: &mut fs::File, event: &CommitEvent) -> Result<(), String> {
541	    let mut line = serde_json::to_vec(event).map_err(|e| format!("encode wal: {e}"))?;
542	    line.push(b'\n');
543	    wal.write_all(&line)
544	        .and_then(|_| wal.flush())
545	        .and_then(|_| wal.sync_all())
546	        .map_err(|e| format!("wal append: {e}"))
547	}
