549	/// 完整状态写入 snapshot.json（临时文件 + fsync + 原子重命名 + 目录 fsync）。
550	fn persist_state(dir: &Path, st: &Inner) -> Result<(), String> {
551	    let state = PersistedState {
552	        versions: st
553	            .versions
554	            .iter()
555	            .map(|v| PersistedVersion {
556	                id: v.id,
557	                saved_at: v.saved_at,
558	                collections: v
559	                    .data
560	                    .iter()
561	                    .map(|(name, records)| PersistedCollection {
562	                        name: name.clone(),
563	                        records: records.clone(),
564	                    })
565	                    .collect(),
566	            })
567	            .collect(),
568	        collections: st
569	            .current
570	            .iter()
571	            .map(|(name, records)| PersistedCollection {
572	                name: name.clone(),
573	                records: records.clone(),
574	            })
575	            .collect(),
576	    };
577	    let mut bytes = serde_json::to_vec(&state).map_err(|e| format!("encode snapshot: {e}"))?;
578	    bytes.push(b'\n');
579	
580	    let target = dir.join("snapshot.json");
581	    let tmp = dir.join("snapshot.json.tmp");
582	    {
583	        let mut f = fs::OpenOptions::new()
584	            .create(true)
585	            .write(true)
586	            .truncate(true)
587	            .open(&tmp)
588	            .map_err(|e| format!("write snapshot tmp: {e}"))?;
589	        f.write_all(&bytes)
590	            .and_then(|_| f.flush())
591	            .and_then(|_| f.sync_all())
592	            .map_err(|e| format!("write snapshot tmp: {e}"))?;
593	    }
594	    fs::rename(&tmp, &target).map_err(|e| format!("rename snapshot: {e}"))?;
595	    if let Ok(d) = fs::File::open(dir) {
596	        let _ = d.sync_all();
597	    }
598	    Ok(())
599	}
