601	/// 清空 WAL（其中的提交已固化进 snapshot.json），并重新以追加模式打开。
602	fn truncate_wal(wal: &mut fs::File, wal_path: &Path) -> Result<(), String> {
603	    {
604	        let mut f = fs::OpenOptions::new()
605	            .create(true)
606	            .write(true)
607	            .truncate(true)
608	            .open(wal_path)
609	            .map_err(|e| format!("truncate wal: {e}"))?;
610	        f.flush()
611	            .and_then(|_| f.sync_all())
612	            .map_err(|e| format!("truncate wal: {e}"))?;
613	    }
614	    // 先关闭旧句柄，再以 append 重新打开供后续提交使用。
615	    let reopened = fs::OpenOptions::new()
616	        .append(true)
617	        .open(wal_path)
618	        .map_err(|e| format!("reopen wal: {e}"))?;
619	    *wal = reopened;
620	    Ok(())
621	}
