623	/// 递归校验字段值：仅允许字符串、整数、布尔、null 与嵌套对象；
624	/// 浮点数与数组一律拒绝。
625	fn validate_value(v: &Value) -> Result<(), String> {
626	    match v {
627	        Value::Null | Value::Bool(_) | Value::String(_) => Ok(()),
628	        Value::Number(n) if n.is_i64() || n.is_u64() => Ok(()),
629	        Value::Number(_) => Err("number must be an integer".to_string()),
630	        Value::Object(map) => {
631	            for (k, child) in map {
632	                validate_value(child).map_err(|e| format!("{k}: {e}"))?;
633	            }
634	            Ok(())
635	        }
636	        Value::Array(_) => Err("arrays are not allowed".to_string()),
637	    }
638	}
