    let v2 = request(&addr, "POST", "/versions", None).body["id"]
        .as_u64()
        .unwrap();
    let r = request(
        &addr,
        "GET",
        &format!("/versions/{v2}/collections/users/records"),
        None,
    );
    let recs = r.body["records"].as_array().unwrap();
    assert_eq!(recs.len(), 1);
    assert_eq!(recs[0]["id"], "u2");
}

